export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResults = [];
  let allThresholdsPassed = true;

  for (const [metric, min] of Object.entries(thresholds)) {
    const evaluation = evaluations.find((e) => e.id === metric);
    const passed = evaluation && typeof evaluation.score === 'number' && evaluation.score >= min;
    if (!passed) allThresholdsPassed = false;
    thresholdResults.push({
      metric,
      min,
      score: evaluation?.score ?? null,
      passed: Boolean(passed)
    });
  }

  return {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations,
    ...(Object.keys(thresholds).length > 0 && {
      passed: allThresholdsPassed,
      thresholds: thresholdResults
    })
  };
}

