function assertFileExists(targetPath: string) {
  if (!fs.existsSync(targetPath)) {
    throw new Error(`File not found: ${targetPath}`);
  }
}

function parseThresholds(thresholdStrings: string[] | undefined, evaluations: any[]): { thresholds: Record<string, number>; errors?: string[] } {
  const thresholds: Record<string, number> = {};
  const errors: string[] = [];

  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { thresholds };
  }

  const validMetricIds = new Set(evaluations.map((e: any) => e.id));

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=(.+)$/);
    if (!match) {
      errors.push(`Malformed threshold: "${thresholdStr}" (expected format: <metric>=<number>)`);
      continue;
    }

    const [, metricId, minStr] = match;
    const min = parseFloat(minStr);

    if (Number.isNaN(min)) {
      errors.push(`Malformed threshold: "${thresholdStr}" (minimum must be a number)`);
      continue;
    }

    if (min < 0 || min > 1) {
      errors.push(`Invalid threshold: "${thresholdStr}" (minimum must be between 0 and 1)`);
      continue;
    }

    if (!validMetricIds.has(metricId)) {
      errors.push(`Unknown metric: "${metricId}" (valid metrics: ${Array.from(validMetricIds).join(', ')})`);
      continue;
    }

    thresholds[metricId] = min;
  }

  return errors.length > 0 ? { thresholds, errors } : { thresholds };
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  const thresholdParse = parseThresholds(options.threshold, evaluations);
  if (thresholdParse.errors && thresholdParse.errors.length > 0) {
    log.error('Invalid threshold specification');
    thresholdParse.errors.forEach((error) => {
      console.error(` - ${error}`);
    });
    process.exit(2);
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: thresholdParse.thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

